package com.optarena.user;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

public class UserDtoHiddenTest {
    @Test
    public void validDtoHasNoErrors() {
        UserDto dto = new UserDto("Alice", "alice@example.com");
        assertTrue(dto.validate().isEmpty(), "expected no errors, got: " + dto.validate());
    }

    @Test
    public void blankNameIsRejected() {
        UserDto dto = new UserDto("   ", "alice@example.com");
        List<String> errors = dto.validate();
        assertTrue(errors.stream().anyMatch(e -> e.toLowerCase().contains("name")),
                "expected a name-related error, got: " + errors);
    }

    @Test
    public void blankEmailIsRejected() {
        UserDto dto = new UserDto("Alice", "");
        List<String> errors = dto.validate();
        assertTrue(errors.stream().anyMatch(e -> e.toLowerCase().contains("email") && e.toLowerCase().contains("blank")),
                "expected an email-blank error, got: " + errors);
    }

    @Test
    public void malformedEmailIsRejected() {
        UserDto dto = new UserDto("Alice", "not-an-email");
        List<String> errors = dto.validate();
        assertTrue(errors.stream().anyMatch(e -> e.toLowerCase().contains("valid")),
                "expected an invalid-email-format error, got: " + errors);
    }
}

package com.optarena.user;

import java.util.ArrayList;
import java.util.List;

public class UserDto {
    private final String name;
    private final String email;

    public UserDto(String name, String email) {
        this.name = name;
        this.email = email;
    }

    public String getName() { return name; }
    public String getEmail() { return email; }

    public List<String> validate() {
        List<String> errors = new ArrayList<>();
        if (name == null || name.trim().isEmpty()) {
            errors.add("name must not be blank");
        }
        if (email == null || email.trim().isEmpty()) {
            errors.add("email must not be blank");
        } else {
            int at = email.indexOf('@');
            int dot = at >= 0 ? email.indexOf('.', at + 1) : -1;
            if (at < 0 || dot < 0) {
                errors.add("email must be a valid email address");
            }
        }
        return errors;
    }
}

